    checklist: ["학년별 적정 어휘량 정착 (초1 1천·중1 2만·고3 5만)?","어휘 학습 4단계 (단어→맥락→유의어→활용) 정착?","유의어·반의어 묶음 학습?","활용 (글쓰기·말하기) 정착?","매일 어휘 학습 + 매주 진단 습관?"],
