    faqs: [
      {q: "초1 어휘 어떻게 시작?", a: "초1은 즐거움이 우선이에요. 한글·일상 단어·그림책 위주로 자연스럽게 시작이 답이에요. 강요 X. 매일 15~20분 + 동화·동요·만화로 노출 + 가족과 함께 읽기. 추천 자료: 그림책 (\"강아지똥\"·\"구름빵\")·동요 책. 1:1 과외에서 발음 + 흥미 형성 추천."},
      {q: "초등 어휘 책 어떤 게 좋나요?", a: "학년별로 달라요. 초1·2: 그림책·\"속담 100\"·\"동요 모음집\". 초3·4: \"초등 필수 어휘 1500\"·\"속담·관용어\". 초5·6: \"초등 어휘력 5000\"·\"교과 어휘\"·\"한자 어휘 입문\". 본인 학년·수준에 맞는 책 1권 100% 정복 후 다음 책. 1:1 과외에서 책 추천 효율적이에요."},
      {q: "단어가 잘 안 외워져요", a: "4단계 학습이 답이에요. (1) 단어: 정확한 뜻·발음·예문. (2) 맥락: 단어가 사용된 글. (3) 유의어·반의어: 묶음 학습. (4) 활용: 본인 글에서 사용. 단순 \"단어 + 뜻\" 암기는 1주일 후 50% 잊어버립니다. 1:1 과외에서 4단계 학습법 시연 추천."},
      {q: "한자 어휘는 언제부터?", a: "초3·4부터 자연스럽게 시작이 답이에요. 한국어 어휘의 70%가 한자어이므로 한자 어휘 학습이 효율적. 다만 한자 자체 외우기 X·\"한자어 의미\" 위주로 학습. 예: 학교 (學 배울 학·校 학교 교) → \"배움의 공간\" 의미 추론. 매주 한자어 5~10개 + 1:1 첨삭이 답이에요."},
    ],
