      body: "문학 문해력은 수능 국어 1·2등급의 또 다른 핵심이에요. 비문학과 함께 점수의 50%를 좌우합니다. 시·소설·수필 등 문학 작품의 맥락을 이해하는 능력이 답입니다. 핵심은 \"문학 3유형 + 맥락 이해 4단계 + 빈출 표현 + 함정 정복\" 4박자예요. 단순 줄거리 파악 X. \"배경 + 인물 + 사건 + 주제\" 4단계 분석이 답이에요. 작가 의도·시대 배경·표현 기법 이해가 1·2등급의 비밀입니다. 매일 30분~1시간 + 매주 문학 5작품 분석이 표준이에요. 1:1 과외에서 약점 유형 진단 + 맞춤 학습 추천."
